struct Params { time: f32 }
@group(0) @binding(0) var<uniform> params: Params;

struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) uv: vec2f,
}

@vertex fn vs_main(@builtin(vertex_index) i: u32) -> VSOut {
  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  var o: VSOut;
  o.pos = vec4f(p[i], 0.0, 1.0);
  o.uv = vec2f(p[i].x * 0.5 + 0.5, 1.0 - (p[i].y * 0.5 + 0.5));
  return o;
}


fn hash21(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = hash21(i);
  let b = hash21(i + vec2f(1.0, 0.0));
  let c = hash21(i + vec2f(0.0, 1.0));
  let d = hash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn rot2(p: vec2f, a: f32) -> vec2f {
  let c = cos(a);
  let s = sin(a);
  return vec2f(c * p.x - s * p.y, s * p.x + c * p.y);
}

fn rotX(p: vec3f, a: f32) -> vec3f {
  let c = cos(a);
  let s = sin(a);
  return vec3f(p.x, c * p.y - s * p.z, s * p.y + c * p.z);
}

fn rotY(p: vec3f, a: f32) -> vec3f {
  let c = cos(a);
  let s = sin(a);
  return vec3f(c * p.x + s * p.z, p.y, -s * p.x + c * p.z);
}

fn sdRoundBox(p: vec2f, b: vec2f, r: f32) -> f32 {
  let q = abs(p) - b + vec2f(r);
  return length(max(q, vec2f(0.0))) + min(max(q.x, q.y), 0.0) - r;
}

fn sdSegment(p: vec2f, a: vec2f, b: vec2f, w: f32) -> f32 {
  let pa = p - a;
  let ba = b - a;
  let h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
  return length(pa - ba * h) - w;
}

fn sdA(p: vec2f) -> f32 {
  let l = sdSegment(p, vec2f(-0.36, -0.52), vec2f(0.0, 0.54), 0.078);
  let r = sdSegment(p, vec2f(0.36, -0.52), vec2f(0.0, 0.54), 0.078);
  let bar = sdRoundBox(p - vec2f(0.0, -0.08), vec2f(0.18, 0.062), 0.016);
  return min(l, min(r, bar));
}

fn sdE(p: vec2f) -> f32 {
  let stem = sdRoundBox(p - vec2f(-0.26, 0.0), vec2f(0.070, 0.52), 0.018);
  let top = sdRoundBox(p - vec2f(0.02, 0.46), vec2f(0.30, 0.070), 0.018);
  let mid = sdRoundBox(p - vec2f(-0.04, 0.02), vec2f(0.24, 0.062), 0.016);
  let bot = sdRoundBox(p - vec2f(0.02, -0.46), vec2f(0.30, 0.070), 0.018);
  return min(min(stem, top), min(mid, bot));
}

fn sdH(p: vec2f) -> f32 {
  let l = sdRoundBox(p - vec2f(-0.26, 0.0), vec2f(0.070, 0.52), 0.018);
  let r = sdRoundBox(p - vec2f(0.26, 0.0), vec2f(0.070, 0.52), 0.018);
  let bar = sdRoundBox(p - vec2f(0.0, 0.02), vec2f(0.28, 0.066), 0.016);
  return min(l, min(r, bar));
}

fn sdI(p: vec2f) -> f32 {
  let stem = sdRoundBox(p, vec2f(0.072, 0.40), 0.018);
  let top = sdRoundBox(p - vec2f(0.0, 0.50), vec2f(0.26, 0.070), 0.018);
  let bot = sdRoundBox(p + vec2f(0.0, 0.50), vec2f(0.26, 0.070), 0.018);
  return min(stem, min(top, bot));
}

fn sdO(p: vec2f) -> f32 {
  return abs(length(p * vec2f(1.08, 0.86)) - 0.42) - 0.078;
}

fn sdT(p: vec2f) -> f32 {
  let bar = sdRoundBox(p - vec2f(0.0, 0.48), vec2f(0.40, 0.070), 0.018);
  let stem = sdRoundBox(p - vec2f(0.0, -0.04), vec2f(0.070, 0.48), 0.018);
  return min(bar, stem);
}

fn sdN(p: vec2f) -> f32 {
  let l = sdRoundBox(p - vec2f(-0.26, 0.0), vec2f(0.070, 0.52), 0.018);
  let r = sdRoundBox(p - vec2f(0.26, 0.0), vec2f(0.070, 0.52), 0.018);
  let diag = sdSegment(p, vec2f(-0.26, 0.46), vec2f(0.26, -0.46), 0.076);
  return min(l, min(r, diag));
}

fn sdR(p: vec2f) -> f32 {
  let stem = sdRoundBox(p - vec2f(-0.26, 0.0), vec2f(0.070, 0.52), 0.018);
  let bowl = abs(length((p - vec2f(0.00, 0.24)) * vec2f(1.20, 1.05)) - 0.24) - 0.070;
  let bowlKeep = max(bowl, -(p.x + 0.04));
  let top = sdRoundBox(p - vec2f(-0.04, 0.46), vec2f(0.20, 0.066), 0.016);
  let mid = sdRoundBox(p - vec2f(-0.04, 0.00), vec2f(0.18, 0.062), 0.016);
  let leg = sdSegment(p, vec2f(-0.02, 0.00), vec2f(0.32, -0.52), 0.076);
  return min(stem, min(min(bowlKeep, top), min(mid, leg)));
}

fn sdS(p: vec2f) -> f32 {
  let pt = (p - vec2f(0.02, 0.22)) * vec2f(1.10, 1.20);
  var top = abs(length(pt) - 0.24) - 0.072;
  top = max(top, -sdRoundBox(pt - vec2f(0.24, -0.08), vec2f(0.22, 0.16), 0.02));
  let pb = (p - vec2f(-0.02, -0.22)) * vec2f(1.10, 1.20);
  var bot = abs(length(pb) - 0.24) - 0.072;
  bot = max(bot, -sdRoundBox(pb - vec2f(-0.24, 0.08), vec2f(0.22, 0.16), 0.02));
  return min(top, bot);
}

fn sdC(p: vec2f) -> f32 {
  let ring = abs(length(p * vec2f(1.08, 0.88)) - 0.42) - 0.078;
  let mouth = sdRoundBox(p - vec2f(0.38, 0.0), vec2f(0.28, 0.18), 0.04);
  return max(ring, -mouth);
}

fn sdL(p: vec2f) -> f32 {
  let stem = sdRoundBox(p - vec2f(-0.24, 0.04), vec2f(0.070, 0.48), 0.018);
  let bot = sdRoundBox(p - vec2f(0.02, -0.46), vec2f(0.30, 0.070), 0.018);
  return min(stem, bot);
}

fn sdF(p: vec2f) -> f32 {
  let stem = sdRoundBox(p - vec2f(-0.24, 0.0), vec2f(0.070, 0.52), 0.018);
  let top = sdRoundBox(p - vec2f(0.02, 0.46), vec2f(0.28, 0.070), 0.018);
  let mid = sdRoundBox(p - vec2f(-0.04, 0.04), vec2f(0.22, 0.062), 0.016);
  return min(stem, min(top, mid));
}

fn sdU(p: vec2f) -> f32 {
  let l = sdRoundBox(p - vec2f(-0.26, 0.14), vec2f(0.070, 0.38), 0.018);
  let r = sdRoundBox(p - vec2f(0.26, 0.14), vec2f(0.070, 0.38), 0.018);
  var bow = abs(length((p - vec2f(0.0, -0.16)) * vec2f(1.02, 1.20)) - 0.26) - 0.070;
  bow = max(bow, p.y + 0.16);
  return min(l, min(r, bow));
}

fn sdK(p: vec2f) -> f32 {
  let stem = sdRoundBox(p - vec2f(-0.26, 0.0), vec2f(0.070, 0.52), 0.018);
  let up = sdSegment(p, vec2f(-0.12, 0.04), vec2f(0.32, 0.52), 0.076);
  let dn = sdSegment(p, vec2f(-0.12, 0.04), vec2f(0.34, -0.52), 0.076);
  return min(stem, min(up, dn));
}

fn letterSDF(p: vec2f, k: i32) -> f32 {
  if (k == 0) { return sdA(p); }
  if (k == 1) { return sdE(p); }
  if (k == 2) { return sdH(p); }
  if (k == 3) { return sdI(p); }
  if (k == 4) { return sdO(p); }
  if (k == 5) { return sdT(p); }
  if (k == 6) { return sdN(p); }
  if (k == 7) { return sdR(p); }
  if (k == 8) { return sdS(p); }
  if (k == 9) { return sdC(p); }
  if (k == 10) { return sdL(p); }
  if (k == 11) { return sdF(p); }
  if (k == 12) { return sdU(p); }
  return sdK(p);
}

fn letterSmeared(p: vec2f, k: i32, trail: vec2f, amt: f32) -> f32 {
  var d = letterSDF(p, k);
  d = min(d, letterSDF(p - trail * 0.22 * amt, k) + 0.034);
  d = min(d, letterSDF(p - trail * 0.44 * amt, k) + 0.072);
  d = min(d, letterSDF(p - trail * 0.68 * amt, k) + 0.118);
  d = min(d, letterSDF(p - trail * 0.94 * amt, k) + 0.170);
  return d;
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.time;
  let scr = (uv - vec2f(0.5)) * vec2f(1.125, 2.0);

  let grain = (noise(uv * 420.0) - 0.5) * 0.034
            + (noise(uv * 1100.0) - 0.5) * 0.014;
  let fiber = (noise(vec2f(uv.x * 18.0, uv.y * 280.0)) - 0.5) * 0.012;
  var paper = vec3f(0.78, 0.775, 0.762) + vec3f(grain + fiber);

  let disk = length(scr * vec2f(1.02, 1.00));
  paper = mix(paper, paper * vec3f(0.94, 0.935, 0.93), smoothstep(1.14, 0.58, disk) * 0.42);

  let camZ = 2.50;
  let fl = 1.54;
  let angX = t * 1.12;
  let angY = t * 0.47 + 0.31;

  let nBand = normalize(vec3f(sin(t * 0.81 + 0.2), 0.22 + 0.18 * sin(t * 0.53), cos(t * 0.81 + 0.2)));
  let nHot = normalize(vec3f(sin(t * 1.05 + 1.1), 0.12, cos(t * 1.05 + 1.1)));

  var dMin = 12.0;
  var heatHit = 0.0;
  var faceHit = 0.0;
  var glow = 0.0;

  for (var i = 0; i < 84; i = i + 1) {
    let fi = f32(i);
    let h1 = hash21(vec2f(fi, 1.7));
    let h2 = hash21(vec2f(fi, 8.3));
    let h3 = hash21(vec2f(fi, 4.1));

    let y0 = 1.0 - (fi + 0.5) / 84.0 * 2.0;
    let rxy = sqrt(max(0.0, 1.0 - y0 * y0));
    let phi = 2.39996322973 * fi + h1 * 0.12;
    let rad = 0.94 + 0.10 * (h2 - 0.5);
    var p0 = vec3f(rxy * cos(phi), y0, rxy * sin(phi)) * rad;

    var p = rotX(p0, angX);
    p = rotY(p, angY);
    p = rotX(p, 0.11 * sin(t * 0.33));

    let depth = camZ - p.z;
    if (depth > 0.22) {
      let proj = p.xy * (fl / depth);
      let kind = i % 14;
      let lsize = (0.072 + 0.028 * h3) * (fl / depth);
      let delta = scr - proj;
      let smearAmt = 0.70 + 0.55 * abs(p.z);
      if (length(delta) < lsize * (1.55 + smearAmt * 0.85)) {
        let tilt = (h1 - 0.5) * 0.28;
        var local = rot2(delta / lsize, tilt);
        let trail = rot2(vec2f(0.0, 1.0), tilt);

        let d = letterSmeared(local, kind, trail, smearAmt);

        let np = normalize(p);
        var heat = exp(-dot(np, nBand) * dot(np, nBand) * 16.0);
        heat = heat + 0.62 * pow(max(dot(np, nHot), 0.0), 7.0);
        heat = clamp(heat, 0.0, 1.0);

        let facing = smoothstep(-0.25, 0.42, p.z);
        let pos = max(d, 0.0);
        glow = glow + heat * facing * exp(-pos * pos * 12.0) * 0.62;
        glow = glow + heat * facing * exp(-pos * pos * 2.6) * 0.16;
        glow = glow + heat * (0.35 + 0.65 * facing) * exp(-pos * pos * 0.9) * 0.06;

        let score = d + (1.0 - facing) * 0.045;
        if (score < dMin) {
          dMin = score;
          heatHit = heat;
          faceHit = facing;
        }
      }
    }
  }

  let aa = 0.028;
  let cover = 1.0 - smoothstep(-aa, aa, dMin);
  let inkCold = vec3f(0.06, 0.055, 0.050);
  let inkWarm = vec3f(0.62, 0.045, 0.028);
  let inkHot = vec3f(0.92, 0.07, 0.03);
  var ink = mix(inkCold, inkWarm, clamp(heatHit * 1.20, 0.0, 1.0));
  ink = mix(ink, inkHot, clamp(heatHit * 1.15 - 0.28, 0.0, 1.0));
  ink = mix(ink, mix(paper * 0.55, ink, 0.72), 1.0 - faceHit);

  var col = mix(paper, ink, cover);
  col = col + vec3f(0.98, 0.08, 0.03) * glow * 0.48;
  col = col + vec3f(1.00, 0.28, 0.05) * glow * glow * 0.22;
  col = col + vec3f(1.00, 0.55, 0.18) * pow(glow, 3.0) * 0.16;

  let warm = clamp(glow * 0.38, 0.0, 0.30);
  col = mix(col, col * vec3f(1.06, 0.93, 0.90) + vec3f(0.09, 0.01, 0.0), warm);

  let vig = smoothstep(1.28, 0.30, length(scr * vec2f(0.95, 0.68)));
  col = col * (0.88 + 0.12 * vig);
  col = pow(clamp(col, vec3f(0.0), vec3f(1.12)), vec3f(0.96));
  return vec4f(col, 1.0);
}
